    cin >> b >> tb;
    string timeStr;
    cin >> timeStr;

    int hh = stoi(timeStr.substr(0, 2));
    int mm = stoi(timeStr.substr(3, 2));
    int simStart = hh * 60 + mm;
    int simEnd = simStart + ta;

    const int dayStart = 5 * 60;          // 05:00 in minutes
    const int dayEnd = 23 * 60 + 59;      // 23:59 in minutes

    int countMeet = 0;

    // Iterate over all buses from B to A
    for (int depB = dayStart; depB <= dayEnd; depB += b) {
        int arrA = depB + tb;

        // Check if this bus is on the road segment overlapping with Simion's trip
        // We need intersection of (depB, arrA) and (simStart, simEnd)
        int startOverlap = max(depB, simStart);
        int endOverlap = min(arrA, simEnd);

        if (startOverlap < endOverlap) {
            // Ensure we don't count encounters exactly at start or end cities
            if (!(startOverlap == simStart && endOverlap == simStart) &&
                !(startOverlap == simEnd && endOverlap == simEnd)) {
                countMeet++;
            }
        }
    }

    cout << countMeet << '\n';
    return 0;
